/**
 * ANEVUM CANONICAL ACCOUNT CLOSURE / V036
 *
 * Strictly staging-gated, owner-authorized and irreversible only for accounts
 * that have NEVER started a Stripe Checkout and have no billing history.
 *
 * Paid or pending-billing accounts MUST use supervised closure after Stripe
 * subscription/cancellation/invoice obligations are independently verified.
 * We must not silently erase the only member-to-customer association while
 * a future recurring charge could still be generated by Stripe.
 *
 * No Stripe operation, account linking, XP grant or cross-tenant mutation.
 */
import {boundedText} from './request-body.mjs';

const PREFIX='/api/v1/member/account-closure';
const HEADERS={
 'cache-control':'private, no-store','content-type':'application/json; charset=utf-8',
 'x-content-type-options':'nosniff','x-robots-tag':'noindex,nofollow,noarchive',
 'referrer-policy':'no-referrer'
};
const out=(payload,status=200)=>Response.json(payload,{status,headers:HEADERS});
const fail=(status,message)=>out({error:message},status);
const one=(db,sql,...args)=>db.prepare(sql).bind(...args).first();
async function rows(db,sql,...args){
 const r=await db.prepare(sql).bind(...args).all();
 if(r?.success===false||!Array.isArray(r?.results))throw Error('Account storage unavailable');
 return r.results;
}
async function ready(env){
 if(env?.CANONICAL_ACCOUNT_CLOSURE_ENABLED!=='true'||!env.MEMBER_DB?.prepare)return false;
 try{
  const found=await rows(env.MEMBER_DB,
   "SELECT name FROM sqlite_master WHERE type='table' AND name IN ('user','session','member_account_closure_guards','supporter_checkout_intents','supporter_checkout_guards','supporter_customers','supporter_subscriptions')");
  return new Set(found.map(r=>r.name)).size===7;
 }catch{return false;}
}
function memberValid(user){
 return typeof user?.id==='string'&&user.id.length>0&&user.id.length<=128&&
  typeof user.email==='string'&&user.emailVerified===true&&user.email.length<=254;
}
async function recentSession(db,session,memberId,now){
 if(typeof session?.id!=='string'||!session.id||!Number.isSafeInteger(now))return false;
 const known=await one(db,
  'SELECT createdAt,expiresAt FROM session WHERE id=? AND userId=?',session.id,memberId);
 // Better Auth SQLite timestamps are milliseconds. Use authoritative D1
 // session times rather than a timestamp provided by the browser.
 const created=Number(known?.createdAt),expires=Number(known?.expiresAt);
 return Number.isSafeInteger(created)&&Number.isSafeInteger(expires)&&
  created>0&&created<=now+30000&&now-created<=600000&&expires>now;
}
async function closureBlockers(db,memberId,now){
 const customer=await one(db,'SELECT member_user_id FROM supporter_customers WHERE member_user_id=?',memberId);
 const subscription=await one(db,'SELECT member_user_id FROM supporter_subscriptions WHERE member_user_id=? LIMIT 1',memberId);
 const intent=await one(db,'SELECT member_user_id FROM supporter_checkout_intents WHERE member_user_id=? LIMIT 1',memberId);
 const pending=await one(db,
  'SELECT member_user_id FROM supporter_checkout_guards WHERE member_user_id=? AND expires_at_ms>?',memberId,now);
 const closing=await one(db,
  'SELECT member_user_id FROM member_account_closure_guards WHERE member_user_id=? AND expires_at_ms>?',memberId,now);
 if(customer||subscription)return 'billing-review';
 if(intent||pending)return 'checkout-review';
 if(closing)return 'in-progress';
 return null;
}
export async function canonicalAccountClosure(request,env,user,session,{now=Date.now()}={}){
 if(!memberValid(user))return fail(403,'Verified account required');
 const url=new URL(request.url);
 if(url.pathname!==PREFIX||url.search)return fail(404,'Not found');
 if(!['GET','POST'].includes(request.method))return fail(405,'Method not allowed');
 if(!await ready(env)){
  return request.method==='GET'
   ?out({available:false,canClose:false,reason:'not-activated',reauthRequired:false})
   :fail(404,'Account closure not activated');
 }
 const db=env.MEMBER_DB;
 try{
  const exists=await one(db,'SELECT id FROM "user" WHERE id=? AND emailVerified=1',user.id);
  if(!exists)return fail(403,'Verified account no longer exists');
  const reason=await closureBlockers(db,user.id,now);
  const fresh=await recentSession(db,session,user.id,now);
  if(request.method==='GET')
   return out({available:true,canClose:!reason,reason,reauthRequired:!fresh});
  // No browser-origin auth or Better Auth token arrives here as a user ID:
  // the enclosing Worker enforces CSRF and supplies the verified session.
  if(reason)return fail(409,reason==='billing-review'
    ?'Billing history requires assisted closure. Manage subscriptions before requesting permanent deletion.'
    :reason==='checkout-review'
      ?'A prior checkout must be verified and closed before deleting this account.'
      :'An account closure is already being processed.');
  if(!fresh)return fail(403,'Sign out and sign in again to verify this request');
  if(!/^application\/json(?:\s*;|$)/i.test(request.headers.get('content-type')||''))
   return fail(400,'Invalid confirmation');
  const raw=await boundedText(request,280);
  if(raw===null)return fail(400,'Confirmation too large');
  let body;
  try{body=JSON.parse(raw)}catch{return fail(400,'Invalid confirmation')}
  if(!body||typeof body!=='object'||Array.isArray(body)||
     Object.keys(body).sort().join(',')!=='confirmation,memberEmail'||
     body.confirmation!=='DELETE MY ANEVUM ACCOUNT'||
     typeof body.memberEmail!=='string'||body.memberEmail!==user.email)
   return fail(400,'Type the exact confirmation phrase and your verified email');
  // Immutable lease blocks simultaneous deletion and supporter Checkout
  // creation. Both operations check the other guard in their atomic INSERT.
  const nonce=crypto.randomUUID();
  const acquired=await rows(db,
   'INSERT INTO member_account_closure_guards(member_user_id,request_nonce,expires_at_ms,created_at_ms) '+
   'SELECT ?,?,?,? WHERE '+
   'NOT EXISTS(SELECT 1 FROM supporter_customers WHERE member_user_id=?) AND '+
   'NOT EXISTS(SELECT 1 FROM supporter_subscriptions WHERE member_user_id=?) AND '+
   'NOT EXISTS(SELECT 1 FROM supporter_checkout_intents WHERE member_user_id=?) AND '+
   'NOT EXISTS(SELECT 1 FROM supporter_checkout_guards WHERE member_user_id=? AND expires_at_ms>?) '+
   'ON CONFLICT(member_user_id) DO UPDATE SET request_nonce=excluded.request_nonce,'+
   'expires_at_ms=excluded.expires_at_ms,created_at_ms=excluded.created_at_ms '+
   'WHERE member_account_closure_guards.expires_at_ms<=? RETURNING request_nonce',
   user.id,nonce,now+600000,now,user.id,user.id,user.id,user.id,now,now);
  if(acquired.length!==1||acquired[0].request_nonce!==nonce)
   return fail(409,'Billing or another closure operation changed. Reload.');
  // Single atomic D1 delete. ON DELETE CASCADE removes sessions, profile,
  // wall and XP rows owned by this canonical identity. Do not remove any
  // billing or customer record: their presence blocks this operation.
  const deleted=await rows(db,
   'DELETE FROM "user" WHERE id=? '+
   'AND EXISTS(SELECT 1 FROM member_account_closure_guards WHERE member_user_id=? AND request_nonce=?) '+
   'AND NOT EXISTS(SELECT 1 FROM supporter_customers WHERE member_user_id=?) '+
   'AND NOT EXISTS(SELECT 1 FROM supporter_subscriptions WHERE member_user_id=?) '+
   'AND NOT EXISTS(SELECT 1 FROM supporter_checkout_intents WHERE member_user_id=?) '+
   'AND NOT EXISTS(SELECT 1 FROM supporter_checkout_guards WHERE member_user_id=? AND expires_at_ms>?) '+
   'RETURNING id',
   user.id,user.id,nonce,user.id,user.id,user.id,user.id,now);
  return deleted.length===1?out({deleted:true,sessionRevoked:true})
   :fail(409,'Account changed during closure. No deletion was confirmed.');
 }catch{return fail(503,'Account closure could not be verified');}
}
